from __future__ import annotations


def render_kuzu_risk_page() -> str:
    return """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kuzu 关联风险扩散</title><style>
:root{font-family:"Microsoft YaHei",Arial,sans-serif;color:#e5e7eb;background:#0b1220}*{box-sizing:border-box}body{margin:0}.bar{padding:14px 22px;border-bottom:1px solid #263246;background:#111827;display:flex;gap:14px;align-items:center}.back{color:#93c5fd;text-decoration:none;border:1px solid #2563eb;border-radius:4px;padding:5px 9px}.brand{font-size:18px;font-weight:700}.hint{font-size:12px;color:#aeb7c2}.stage{padding:18px;max-width:1500px;margin:auto}.tools{display:flex;gap:12px;align-items:center;margin-bottom:12px;flex-wrap:wrap}.tools input{width:72px;background:#111827;color:#fff;border:1px solid #475569;border-radius:4px;padding:7px}.tools input[type=checkbox]{width:auto;padding:0;accent-color:#2563eb}.tools button{background:#2563eb;color:#fff;border:0;border-radius:4px;padding:8px 12px;cursor:pointer}.legend{display:flex;gap:10px;font-size:12px;color:#cbd5e1;flex-wrap:wrap}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:4px}.board{height:390px;border:1px solid #334155;border-radius:8px;background:#101826;overflow:hidden}.board canvas{width:100%;height:100%;display:block;touch-action:none;cursor:grab}.board canvas:active{cursor:grabbing}.caption{padding:10px 0 16px;color:#b8cce1;font-size:13px}.caption b{color:#fff}.caption span{color:#85d3ff}.detail{border-top:1px solid #334155;padding-top:15px}.detail h2{font-size:16px;margin:0 0 12px}.flow{display:grid;grid-template-columns:135px 205px minmax(0,1fr);gap:26px;align-items:center}.subject{text-align:center;position:relative}.subject:after{content:"";position:absolute;top:50%;left:100%;width:26px;border-top:2px solid #58c4ff}.subject b{display:flex;align-items:center;justify-content:center;width:92px;height:92px;border-radius:50%;margin:auto;background:#ff2638;border:3px solid #ffd6dc;font-size:18px;box-shadow:0 0 0 7px rgba(255,38,56,.14)}.subject small{display:block;color:#a8bfd7;font-size:12px;margin-top:8px}.groups{display:grid;gap:8px}.group{font:inherit;text-align:left;color:#dceaf9;background:#10233c;border:1px solid #365879;border-left:6px solid #6d87a7;border-radius:7px;padding:9px 10px;cursor:pointer}.group strong{display:block;font-size:13px}.group span{display:block;color:#9fb6cf;font-size:11px;margin-top:3px}.group.active{border-left-color:#58c4ff;background:#183959;outline:1px solid #58c4ff}.cluster{border:1px solid #355573;border-radius:8px;background:#0e1c2f;padding:11px 13px}.cluster header{display:flex;justify-content:space-between;gap:8px;font-size:14px}.cluster header span{font-size:12px;color:#9fb9d5}.people{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}.person{min-width:78px;padding:7px 9px;border-radius:5px;background:#602d38;border:1px solid #e76b7d;text-align:center;font-size:12px}.person.mid{background:#654126;border-color:#eaa05a}.person.stop{background:#164a3e;border-color:#3ec589}.person strong{display:block}.person small{display:block;color:#d7e4f2;font-size:11px;margin-top:2px}.empty{color:#9fb6cf;font-size:13px}@media(max-width:700px){.bar{padding:12px}.stage{padding:14px}.board{height:340px}.flow{grid-template-columns:1fr;gap:13px}.subject{display:flex;align-items:center;gap:13px;text-align:left}.subject b{margin:0;flex:0 0 auto}.subject:after{display:none}.groups{grid-template-columns:repeat(2,minmax(0,1fr))}}</style></head><body>
<header class="bar"><a class="back" id="back" href="/">← 返回账户</a><span class="brand">Kuzu 关联风险扩散</span><span class="hint">上方按账户扩散深度定位；下方查看关系证据</span><span class="hint" id="status">读取中…</span></header>
<main class="stage"><div class="tools"><label>扩散阈值 <input id="threshold" type="number" min="1" max="100" value="20"></label><label title="全平台同步开平仓核验会明显增加耗时"><input id="includeToxic" type="checkbox"> 包含 Toxic 同步订单（较慢）</label><button id="reload">重新计算</button><span class="legend"><span><i class="dot" style="background:#ff2638"></i>问题账户</span><span><i class="dot" style="background:#ff6976"></i>高传播分</span><span><i class="dot" style="background:#f5a64b"></i>更外层</span><span><i class="dot" style="background:#35c285"></i>停止扩散</span><span><i class="dot" style="background:#58c4ff"></i>当前账户路径</span></span></div><div class="board"><canvas id="overview" aria-label="按扩散深度定位的全局关系图"></canvas></div><div class="caption"><b id="location">当前坐标：-</b> <span id="path">选择上方账户查看其所在层和扩散路径。</span></div><section class="detail"><h2>当前账户细查</h2><div class="flow"><div class="subject"><b id="selected">-</b><small id="selectedNote">-</small></div><div class="groups" id="groups"></div><article class="cluster"><header><b id="evidence">-</b><span id="evidenceNote">-</span></header><div class="people" id="people"></div></article></div></section></main>
<script>
const canvas=document.getElementById('overview'),ctx=canvas.getContext('2d'),threshold=document.getElementById('threshold'),status=document.getElementById('status'),groups=document.getElementById('groups'),people=document.getElementById('people');let data=null,selectedId='',activeType='',view={scale:1,x:0,y:0},drag=null,layout=new Map();
function relationMap(){return new Map((data.relationTypes||[]).map(x=>[x.id,x.label]))}function accounts(){return data.entities.filter(x=>x.type==='account')}function byId(){return new Map(data.entities.map(x=>[x.id,x]))}function primary(node){return (node.scoreLedger||[])[0]||null}function parent(node){let current=node,seen=new Set(),map=byId();while(current&&!seen.has(current.id)){seen.add(current.id);const ledger=primary(current);if(!ledger)return null;const from=map.get(ledger.from);if(!from)return null;if(from.type==='account')return from;current=from}return null}
function accountDepth(node){if(node.isSubject)return 0;let depth=0,current=node,seen=new Set();while(current&&!current.isSubject&&!seen.has(current.id)){seen.add(current.id);const next=parent(current);if(!next){return Math.max(1,Math.ceil(Number(node.hops||1)/2))}depth++;current=next}return Math.max(1,depth)}function branchType(node){const ledger=primary(node);return ledger?ledger.type:'unknown'}function route(node){const result=[];let current=node,seen=new Set();while(current&&!seen.has(current.id)){result.unshift(current);seen.add(current.id);current=parent(current)}return result}
function color(node,depth){if(node.isSubject)return'#ff2638';if(!node.expandable)return'#35c285';const intensity=Math.max(.15,Math.min(1,(Number(node.score||0)/100)*Math.pow(.78,Math.max(0,depth-1))));return `hsl(12 90% ${78-intensity*38}%)`}
function renderOverview(){if(!data)return;const r=canvas.getBoundingClientRect(),w=r.width,h=r.height,all=accounts(),subject=all.find(x=>x.isSubject),types=[...new Set(all.filter(x=>!x.isSubject).map(branchType))].sort(),radius=Math.max(52,Math.min(w,h)*.15);layout=new Map();layout.set(subject.id,{x:w*.52,y:h*.53,depth:0,type:'subject'});types.forEach((type,index)=>{const items=all.filter(x=>!x.isSubject&&branchType(x)===type).sort((a,b)=>Number(b.score)-Number(a.score));const base=-Math.PI/2+index*(Math.PI*2/types.length);items.forEach((node,itemIndex)=>{const depth=Math.min(4,accountDepth(node)),offset=(itemIndex-(items.length-1)/2)*Math.min(.13,.8/Math.max(1,items.length));layout.set(node.id,{x:w*.52+Math.cos(base+offset)*radius*depth,y:h*.53+Math.sin(base+offset)*radius*depth,depth,type})})});ctx.fillStyle='#101826';ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(view.x,view.y);ctx.scale(view.scale,view.scale);for(let ring=1;ring<=4;ring++){ctx.strokeStyle='rgba(112,144,178,.45)';ctx.lineWidth=1;ctx.setLineDash([4,6]);ctx.beginPath();ctx.arc(w*.52,h*.53,radius*ring,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#93acc6';ctx.font='11px Microsoft YaHei';ctx.fillText('第 '+ring+' 圈 · '+all.filter(x=>accountDepth(x)===ring).length+' 个账户',w*.52-radius*ring-58,h*.53-radius*ring+7)}const selected=byId().get(selectedId)||subject,routeIds=new Set(route(selected).map(x=>x.id)),pathNodes=route(selected);for(let i=1;i<pathNodes.length;i++){const a=layout.get(pathNodes[i-1].id),b=layout.get(pathNodes[i].id);if(a&&b){ctx.strokeStyle='#58c4ff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}for(const node of all){const p=layout.get(node.id),depth=p.depth,current=node.id===selectedId,onRoute=routeIds.has(node.id),size=node.isSubject?12:depth===1?5.5:depth===2?4.5:3.6;if(current){ctx.strokeStyle='rgba(88,196,255,.36)';ctx.lineWidth=8;ctx.beginPath();ctx.arc(p.x,p.y,15,0,Math.PI*2);ctx.stroke()}else if(onRoute){ctx.strokeStyle='rgba(88,196,255,.18)';ctx.lineWidth=5;ctx.beginPath();ctx.arc(p.x,p.y,size+4,0,Math.PI*2);ctx.stroke()}ctx.fillStyle=color(node,depth);ctx.globalAlpha=depth>=3?.65:1;ctx.beginPath();ctx.arc(p.x,p.y,current?7:size,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;if(current||node.isSubject){ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,current?7:size,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff';ctx.font='500 11px Microsoft YaHei';ctx.textAlign='center';ctx.fillText(node.label,p.x,p.y-(node.isSubject?19:16));ctx.textAlign='start'}}ctx.restore()}
function typeGroups(node){const result=[],labels=relationMap();for(const edge of data.relationships){if(edge.source===node.id||edge.target===node.id){if(!result.includes(edge.type))result.push(edge.type)}}for(const ledger of node.scoreLedger||[]){if(!result.includes(ledger.type))result.push(ledger.type)}return result.sort((a,b)=>(labels.get(a)||a).localeCompare(labels.get(b)||b))}function peers(node,type){const map=byId(),ids=new Set(),connectors=new Set([node.id]);for(const edge of data.relationships)if(edge.type===type&&(edge.source===node.id||edge.target===node.id))connectors.add(edge.source===node.id?edge.target:edge.source);for(const connector of connectors)for(const edge of data.relationships)if(edge.type===type&&(edge.source===connector||edge.target===connector)){const other=edge.source===connector?edge.target:edge.source;const item=map.get(other);if(item&&item.type==='account'&&item.id!==node.id)ids.add(item.id)}return [...ids].map(id=>map.get(id)).sort((a,b)=>Number(b.score)-Number(a.score)).slice(0,8)}
function renderDetail(){const node=byId().get(selectedId);if(!node)return;const depth=accountDepth(node),labels=relationMap(),types=typeGroups(node);if(!types.length)types.push(branchType(node));if(!types.includes(activeType))activeType=types[0];document.getElementById('location').textContent='当前坐标：'+node.label;document.getElementById('path').textContent='— 第 '+depth+' 圈 · '+(labels.get(branchType(node))||'关联支路')+' · 路径：'+route(node).map(x=>x.label).join(' → ');document.getElementById('selected').textContent=node.label;document.getElementById('selectedNote').textContent='第 '+depth+' 圈 · 传播分 '+Number(node.score||0).toFixed(1);groups.replaceChildren();for(const type of types){const button=document.createElement('button');button.type='button';button.className='group'+(type===activeType?' active':'');const title=document.createElement('strong');title.textContent=labels.get(type)||type;const note=document.createElement('span');note.textContent=(type===branchType(node)?'当前最强线索':'附加线索');button.append(title,note);button.addEventListener('click',()=>{activeType=type;renderDetail()});groups.append(button)}const related=peers(node,activeType),edge=data.relationships.find(x=>x.type===activeType&&(x.source===node.id||x.target===node.id));document.getElementById('evidence').textContent=labels.get(activeType)||activeType;document.getElementById('evidenceNote').textContent=(edge&&edge.evidence&&edge.evidence[0])||('关联账户 '+related.length+' 个');people.replaceChildren();if(!related.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='该线索未发现可显示的其他账户。';people.append(empty)}for(const item of related){const card=document.createElement('div');card.className='person'+(!item.expandable?' stop':accountDepth(item)>1?' mid':'');const name=document.createElement('strong');name.textContent=item.label;const note=document.createElement('small');note.textContent=Number(item.score||0).toFixed(1)+' · '+accountDepth(item)+' 跳';card.append(name,note);card.addEventListener('click',()=>{selectedId=item.id;activeType='';renderOverview();renderDetail()});people.append(card)}}
function fit(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);renderOverview()}function world(ev){const r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left-view.x)/view.scale,y:(ev.clientY-r.top-view.y)/view.scale}}window.addEventListener('resize',fit);canvas.addEventListener('wheel',ev=>{ev.preventDefault();const r=canvas.getBoundingClientRect(),before=world(ev),factor=ev.deltaY<0?1.12:1/1.12,next=Math.max(.45,Math.min(2.5,view.scale*factor));view.scale=next;view.x=ev.clientX-r.left-before.x*next;view.y=ev.clientY-r.top-before.y*next;renderOverview()},{passive:false});canvas.addEventListener('pointerdown',ev=>{drag={x:ev.clientX,y:ev.clientY,viewX:view.x,viewY:view.y};canvas.setPointerCapture(ev.pointerId)});canvas.addEventListener('pointermove',ev=>{if(!drag)return;view.x=drag.viewX+ev.clientX-drag.x;view.y=drag.viewY+ev.clientY-drag.y;renderOverview()});canvas.addEventListener('pointerup',()=>{drag=null});canvas.addEventListener('click',ev=>{if(!data)return;const point=world(ev);let closest=null,distance=15;for(const node of accounts()){const p=layout.get(node.id),d=Math.hypot(point.x-p.x,point.y-p.y);if(d<distance){closest=node;distance=d}}if(closest){selectedId=closest.id;activeType='';renderOverview();renderDetail()}});
const params=new URLSearchParams(location.search),target=params.get('account')||'',includeToxic=document.getElementById('includeToxic');let controller=null;if(target)document.getElementById('back').href='/account/'+encodeURIComponent(target)+'?'+params.toString();function apiUrl(value){if(!target)return '/api/kuzu-risk/graph?threshold='+value;const query=new URLSearchParams();for(const key of ['platform','server','symbol'])if(params.get(key))query.set(key,params.get(key));query.set('threshold',String(value));if(includeToxic.checked)query.set('include_toxic','true');return '/api/accounts/by-login/'+encodeURIComponent(target)+'/relationship-network?'+query.toString()}async function load(){if(controller)controller.abort();controller=new AbortController();const active=controller,value=Math.max(1,Math.min(100,Number(threshold.value)||20));threshold.value=value;status.textContent=includeToxic.checked?'读取关系与 Toxic 同步订单中…':'读取关系并评分中…';const timeout=setTimeout(()=>active.abort(),20000);try{const response=await fetch(apiUrl(value),{cache:'no-store',signal:active.signal});if(!response.ok)throw new Error();data=await response.json();selectedId=data.subjectId||data.entities.find(x=>x.isSubject)?.id||'';activeType='';view={scale:1,x:0,y:0};fit();renderDetail();status.textContent='规则 '+data.summary.ruleVersion+(data.queryBudgetExhausted?' · 查询预算已到，已返回部分图谱':data.truncated?' · 已触发安全上限':' · 完成')}catch(error){status.textContent=error.name==='AbortError'?'查询超过 20 秒，已停止等待。':'图谱读取失败'}finally{clearTimeout(timeout);if(controller===active)controller=null}}document.getElementById('reload').addEventListener('click',load);load();
</script></body></html>"""
